function fixedStep(dt){const b=S.battle;if(!b||b.paused||b.result)return;groundPools(dt);if(b.finale){finaleStep(dt);return;}b.time+=dt;if(b.leaders)for(const team of [0,1]){const leader=b.actors.find(a=>a.id===b.leaders[team]);if(leader?.g.dead&&!b.leaderLost?.[team]){b.leaderLost??=[false,false];b.leaderLost[team]=true;b.moraleBonus[team]=-4;battleLog('Anführer gefallen · Moral sinkt.');}}if(b.benchmark&&b.time>=(M.benchmarkTimeLimit||120)){M.endBenchmark(-1,'Zeitlimit · '+(M.benchmarkTimeLimit||120)+' Simulationssekunden');return;}for(const a of b.actors){const x=a.x,y=a.y,phase=a.phase||0;resolveStrike(a,dt*combatStepRate);updateActor(a,dt*combatStepRate);updateLocomotion(a,x,y,phase,dt*combatStepRate);}collisionPairs(b);stepProjectiles(dt);for(const a of b.actors)if(a.g.dead&&!a.death)a.death=true;const live=[0,1].map(team=>b.actors.filter(a=>a.team===team&&!a.down&&!a.surrendered&&!a.g.dead).length);b.moralePressure=[Math.min(6,Math.max(0,live[1]-live[0])*2),Math.min(6,Math.max(0,live[0]-live[1])*2)];if(!live[0]||!live[1]){startFinale(live[0]>0?0:live[1]>0?1:-1);return}if(b.time-b.lastSave>=5){b.lastSave=b.time;b.projectiles=shots.filter(p=>p.active).map(p=>({...p}));b.limbs=M.limbs;b.stains=M.stains;M.persist()}}

function startFinale(winner,reason=''){const b=S.battle;if(b?.benchmark&&!M.benchmarkFinale){M.endBenchmark(winner,reason);return;}if(!b||b.finale)return;for(const p of shots)if(p.active)landProjectile(p);b.projectiles=[];b.finale={version:2,winner,reason,elapsed:0,index:0,stage:'cheer',text:winner===-1?'UNENTSCHIEDEN':winner===0?S.schoolName.toUpperCase()+' TRIUMPHIERT':b.opponent.toUpperCase()+' TRIUMPHIERT',judgments:winner<0?[]:b.actors.filter(a=>a.team!==winner&&a.down&&!a.g.dead).map(a=>({id:a.id,name:a.g.name,execute:rng()<1/3,method:rng()<.35?'Durchtrennung':'Enthauptung',done:false}))};for(const a of b.actors){delete a.rearFinish;delete a.grabbedBy;delete a.pendingStrike;a.wind=0;a.swing=0;a.hit=0;a.roll=0;a.kickTimer=0;a.kneeTimer=0;a.stagger=0;a.dodgeTimer=0;a.sandKick=0;a.wipeTimer=0;a.chargeTimer=0;a.jumpTimer=0;a.block=false;a.guardTime=0;a.moveSpeed=0;if(a.team===winner&&!a.down&&!a.g.dead&&!a.surrendered){a.state='celebrate';a.fallTimer=0}}crowd(4);M.sound?.('win');battleLog('Die Waffen ruhen. Die Sieger feiern.');M.persist()}

function rearFollowPose(elapsed){const t=Math.max(0,elapsed);return {kick:t>.16?Math.max(0,.48-(t-.16)):0,fall:clamp((t-.38)/.4,0,1),head:-.32*clamp(t/.18,0,1),slide:13.125*(1-Math.pow(1-clamp((t-.38)/.35,0,1),2))};}
function stepFinishPush(dt){const b=S.battle;if(!b||b.paused)return;for(const a of b.actors){const f=a.finishPush;if(f){const victim=b.actors.find(x=>x.id===f.target);if(a.g.dead||a.down||a.fallTimer>0||!victim?.g.dead){a.finishPush=null;a.postKickPose=0;continue;}f.elapsed+=dt;victim.finishReaction=f.elapsed;a.state='finishpush';a.postKickPose=f.elapsed>.16&&M.limb(a.g,['rt','rsh','rf'])>.45?rearFollowPose(f.elapsed).kick:0;a.moveSpeed=0;if(f.elapsed>=.38&&!f.contact){f.contact=true;victim.finishSlide={left:.35,angle:f.angle};M.emit(victim.x,victim.y,6,'#bda579',35);M.sound?.('fall');}if(f.elapsed>=.7){a.finishPush=null;a.postKickPose=0;a.cool=Math.max(a.cool,.35);}}if(a.finishSlide){const t=a.finishSlide;const step=Math.min(dt,t.left);move(a,Math.cos(t.angle)*75*(t.left/.35)*step,Math.sin(t.angle)*75*(t.left/.35)*step);t.left=Math.max(0,t.left-dt);if(!t.left)a.finishSlide=null;}}}
// Full stride in world pixels: short quick steps when creeping, longer steps
// when running. Display scale matters for village figures, not combat speed.
function walkStride(g,speed,renderScale=1){
 const size=g.height/180*renderScale,legs=Math.min(M.limb(g,['lt','lsh','lf']),M.limb(g,['rt','rsh','rf']));
 const cadence=.95+.65*clamp(speed/(95*renderScale),0,1);
 return clamp(speed/cadence,4*size,44*size*(.7+.3*legs));
}
function updateLocomotion(a,x,y,phase,dt,renderScale=1){const moving=['move','circle','flank','charge','retreat'].includes(a.state)&&!a.down&&!a.g.dead&&!(a.fallTimer>0)&&!a.grabbedBy&&!a.rearFinish&&!a.finishPush;const dx=a.x-x,dy=a.y-y,d=Math.hypot(dx,dy),speed=moving?d/Math.max(.001,dt):0;a.gaitSpeed=(a.gaitSpeed||0)+(speed-(a.gaitSpeed||0))*(1-Math.exp(-14*dt));a.moveSpeed=speed;a.velocityX=moving?clamp(dx/Math.max(.001,dt),-160,160):0;a.velocityY=moving?clamp(dy/Math.max(.001,dt),-160,160):0;a.phase=phase;if(speed>1){a.gaitStride=walkStride(a.g,speed,renderScale);a.phase=(phase+d*TAU/a.gaitStride)%TAU;const blend=1-Math.exp(-12*dt),forward=dx/d*(Math.cos(a.a)>=0?1:-1);a.gaitForward=(a.gaitForward??forward)+(forward-(a.gaitForward??forward))*blend;a.gaitDepth=(a.gaitDepth??dy/d)+(dy/d-(a.gaitDepth??dy/d))*blend;}else{a.gaitForward??=1;a.gaitDepth??=0;}}

function presentationStep(dt){stepFinishPush(dt);const b=S.battle;if(!b||b.paused)return;if(b.benchmark)b.cinematic=null;for(const a of b.actors){if(a.neckFinishTimer>0)a.neckFinishTimer=Math.max(0,a.neckFinishTimer-dt*(b.cinematic?.18:1));if(a.finishReaction!==undefined&&!b.actors.some(x=>x.finishPush?.target===a.id))a.finishReaction=Math.min(1.2,a.finishReaction+dt);}if(b.verdictCamera)b.verdictCamera.mix=Math.min(1,(b.verdictCamera.mix||0)+dt*3);if(b.cinematic){b.cinematic.left=Math.max(0,b.cinematic.left-dt);if(!b.cinematic.left)b.cinematic=null;}}
function setFinaleStage(stage,text){const b=S.battle,f=b.finale;f.stage=stage;f.elapsed=0;if(text)f.text=text;M.persist();}
function currentJudgment(){const b=S.battle;return b?.finale?.judgments[b.finale.index];}
function prepareVerdictAction(skip=false){const b=S.battle,f=b?.finale,j=currentJudgment();if(!f||!j||j.done)return;const victim=b.actors.find(a=>a.id===j.id);if(!victim){j.done=true;f.index++;setFinaleStage('cheer');return;}const executor=b.actors.filter(a=>a.team===f.winner&&!a.g.dead&&!a.down&&!a.surrendered).sort((a,c)=>dist(a,victim)-dist(c,victim))[0];if(!victim||victim.g.dead||!executor){j.done=true;f.index++;setFinaleStage('cheer');return;}/* Dritte Art des Urteils: wer mit Speer, Dreizack, Hellebarde, Wurfspeer oder Dolch richtet, setzt den Gnadenstoß ins Herz */if(j.execute&&['spear','trident','halberd','javelin','dagger'].includes(weapon(executor).id))j.method='Gnadenstoß';f.executor=executor.id;executor.ceremonialBlade=j.method!=='Gnadenstoß'&&j.execute&&(!weapon(executor).bladed||weapon(executor).ammo>0);const point=verdictAnchor(victim,j.method);executor.contactPoint=point;f.standX=clamp(point.x-58,marginX(80),arenaSize().width-marginX(110));f.standY=clamp(point.y+45,marginY(135),arenaSize().height-marginY(90));b.verdictCamera={x:clamp((f.standX+victim.x)/2+10,marginX(105),arenaSize().width-marginX(110)),y:victim.y-25,mix:b.verdictCamera?.mix||0};f.text=j.name.toUpperCase()+(j.execute?' · KEINE GNADE':' · BEGNADIGT');executor.target=victim.id;executor.state='move';executor.block=false;executor.guardTime=0;executor.roll=0;executor.jumpTimer=0;executor.sandKick=0;executor.wipeTimer=0;executor.chargeTimer=0;executor.fallTimer=0;f.fromX=executor.x;f.fromY=executor.y;if(skip){executor.x=f.standX;executor.y=f.standY;executor.a=0;setFinaleStage('act');}else setFinaleStage('approach');crowd(j.execute?2:3);battleLog(f.text);}
function skipVerdict(){const b=S.battle,f=b?.finale;if(!f||b.paused||!['cheer','verdict','sentence'].includes(f.stage)||!currentJudgment())return false;prepareVerdictAction(true);return true;}
function finaleStep(dt){const b=S.battle,f=b.finale;f.elapsed+=dt;for(const a of b.actors){a.swing=Math.max(0,(a.swing||0)-dt);a.mercyTimer=Math.max(0,(a.mercyTimer||0)-dt);if(a.state==='celebrate')a.phase+=dt*4;}const j=currentJudgment();if(!j){if(f.elapsed>2.1&&!b.cinematic){b.verdictCamera=null;finish(f.winner,f.reason);}return;}const victim=b.actors.find(a=>a.id===j.id);if(f.stage==='cheer'){if(f.elapsed<2.2)return;b.verdictCamera={x:clamp(victim.x-43,marginX(105),arenaSize().width-marginX(110)),y:victim.y-25,mix:0};setFinaleStage('verdict','DAS PUBLIKUM ENTSCHEIDET · '+j.name.toUpperCase());crowd(2);return;}if(f.stage==='verdict'){if(f.elapsed<1.8)return;setFinaleStage('sentence',j.execute?j.name.toUpperCase()+' · KEINE GNADE':mercyText(j,victim));M.sound?.(j.execute?'verdictDeath':'mercy');return;}if(f.stage==='sentence'){if(f.elapsed>=1.6)prepareVerdictAction();return;}const actor=b.actors.find(a=>a.id===f.executor);if(f.stage==='approach'){const t=clamp(f.elapsed/1.1,0,1);actor.x=f.fromX+(f.standX-f.fromX)*t;actor.y=f.fromY+(f.standY-f.fromY)*t;actor.a=0;actor.phase+=dt*10;actor.moveSpeed=60;if(t>=1){actor.moveSpeed=0;setFinaleStage('act');}return;}if(f.stage==='act'){if(j.done){setFinaleStage('after');return;}actor.moveSpeed=0;actor.a=0;actor.state=j.execute?'execute':'mercy';if(j.execute){actor.windMax=1.05;actor.wind=f.elapsed<1.05?1.05-f.elapsed:0;actor.attackA=0;if(f.elapsed>=1.05){actor.swingMax=1;actor.swing=Math.max(0,1-(f.elapsed-1.05));actor.swingKind=j.method==='Gnadenstoß'?'thrust':'slash';}}else{actor.wind=0;victim.mercyTimer=2;}
if(f.elapsed<(j.execute?1.6:1.05))return;actor.wind=0;j.done=true;f.impactTime=b.time+f.elapsed;if(j.execute&&!victim.g.dead){recordAttack(actor,j.method==='Durchtrennung'?'verdictSplit':'verdictHead');actor.swingMax=1;actor.swing=.45;actor.swingKind='slash';if(j.method==='Durchtrennung')bisect(actor,victim);else if(j.method==='Gnadenstoß'){const p=victim.g.body.chest;p.hp=0;p.bleed+=20;M.recordWound(victim.g,'chest','Durchstochen',actor.g.name,weapon(actor).name);M.noteInjury(victim.g,'chest','Durchstochen',actor.g.name,weapon(actor).name);death(victim,'Gnadenstoß',actor);}else {j.method='Enthauptung';sever(actor,victim,'head');}b.cinematic={x:b.verdictCamera?.x||victim.x,y:victim.y-24,left:2.1,duration:2.1,kind:j.method.toUpperCase()};}else{j.execute=false;victim.mercyTimer=3.1;actor.state='mercy';M.sound?.('mercy');floater(victim.x-35,victim.y-42,'DARF LEBEN','#a9d3b4');crowd(3);}if(!j.execute)battleLog(mercyText(j,victim));setFinaleStage('after',j.execute?j.name.toUpperCase()+' · '+j.method.toUpperCase():mercyText(j,victim));return;}if(f.stage==='after'){if(f.elapsed<2.1||b.cinematic)return;if(actor){actor.wind=0;actor.ceremonialBlade=false;actor.state='celebrate';}f.index++;if(f.index<f.judgments.length){b.verdictCamera=null;setFinaleStage('cheer','DAS NÄCHSTE URTEIL');}else{f.elapsed=0;M.persist();}return;}}

function finish(winner,reason=''){const b=S.battle;if(b?.benchmark){M.endBenchmark(winner,reason);return;}if(!b||b.result)return;b.result={winner,reason};try{M.workshop?.defeated?.(b);}catch(e){console.warn(e);}M.worldFinish?.(b,winner);const won=winner===0,L=M.leagues[b.league],team=b.actors.filter(a=>a.team===0);let reward=won?L.reward*(b.champion?1.3:1):Math.round(L.reward*.18),fame=won?20+b.league*14:5;let tournamentResult='';if(S.challenge&&!b.openArena){if(won&&b.league===(S.challenge.league??b.league))reward=S.challenge.reward;S.challenge=null}if(b.challengeData)reward=won?b.challengeData.reward:Math.round(b.challengeData.reward*.18);else reward*=team.length/3;if(S.sponsor&&won)reward*=1+S.sponsor.bonus;reward*=1+Math.min(.25,team.reduce((n,a)=>n+a.g.fame,0)/10000);if(b.openArena)reward=M.arenaPrize(b,won)*team.length/3;if(S.tournament){if(won&&S.tournament.round<3){S.tournament.round++;tournamentResult='Runde geschafft. Nächste Runde: '+S.tournament.round+'/3.'}else if(won){if(S.tournament.type==='qualification'){S.league=Math.min(6,S.league+1);S.fightLeague=S.league;tournamentResult='AUFSTIEG: '+M.leagues[S.league].name;fame+=100;reward+=L.reward*2}else{const def=M.tournaments.find(t=>t.id===S.tournament.id);reward+=L.reward*def.mult*3;tournamentResult='TURNIERSIEG!';fame+=80}S.tournament=null}else{tournamentResult='Turnier ausgeschieden.';S.tournament=null}}reward=Math.round(reward);S.gold+=reward;S.stats.earned+=reward;S.fame+=fame;S.stats.battles++;if(won)S.wins++;else S.losses++;S.rank[b.league]=Math.max(0,S.rank[b.league]+(won?25+(b.champion?15:0):winner===-1?0:-12));for(const a of team){const g=a.g;if(g.dead)continue;if(won)g.wins++;else g.losses++;g.fame+=won?12+b.league*7:3;M.applyLearningBonus(a);g.fatigue=clamp(g.fatigue+18+b.time/18,0,100);g.stats.morale=clamp(g.stats.morale+(won?6:-5),10,g.caps.stats.morale);for(const p of Object.values(g.body)){p.bleed=0;p.grade=M.injuryGrade(p)}g.history.unshift({day:S.day,text:(won?'Sieg':'Niederlage')+' gegen '+b.opponent+' · '+Math.round(a.damage)+' Schaden.'});}
const loot=[];if(won){const pool=b.actors.filter(a=>a.team===1&&(a.down||a.g.dead)).flatMap(a=>[M.gear(a.g,'weapon'),M.gear(a.g,'secondary'),M.gear(a.g,'shield'),...M.armorItems(a.g)].filter(Boolean));const count=(b.champion||rng()<.45)?(rng()<.12?2:1):0;for(let n=0;n<count&&pool.length;n++){const original=pool.splice(Math.floor(rng()*pool.length),1)[0],item=M.copy(original);item.id=M.uid();M.worldLoot?.(item,original,b);item.durability=Math.max(1,Math.round(Math.min(item.durability,item.maxDurability*rnd(.35,.82))));item.source=b.opponent;if(S.inventory.length<M.storageCapacity()){S.inventory.push(item);loot.push({name:M.itemName(item),id:item.id,condition:Math.round(item.durability/item.maxDurability*100),sold:0})}else{const gold=Math.round(M.itemPrice(item.kind,item.def,item.q)*.3*item.durability/item.maxDurability);S.gold+=gold;S.stats.earned+=gold;loot.push({name:M.itemName(item),condition:Math.round(item.durability/item.maxDurability*100),sold:gold})}}if(loot.length)M.log('Beute aus der Arena: '+loot.map(x=>x.name).join(', '));}
const report={recipes:M.workshop?.battleRecipes?.(b.id)||[],arenaName:b.openArena?.name,attackSummary:b.actors.map(a=>({id:a.id,name:a.g.name,team:a.team,attacks:a.attacks||{}})),verdicts:b.finale?.judgments||[],loot,id:b.id,day:S.day,won,draw:winner===-1,reason,opponent:b.opponent,time:b.time,gold:reward,fame,league:b.league,tournament:tournamentResult,actors:team.map(a=>({id:a.g.id,name:a.g.name,damage:Math.round(a.damage),taken:Math.round(a.taken),kills:a.kills,crits:a.crits,blocks:a.blocks,dodges:a.dodges,falls:a.falls||0,rearHits:a.rearHits||0,xpMultiplier:a.xpMultiplier||1,learning:a.learning||{},charges:a.charges||0,backsteps:a.backsteps||0,dead:a.g.dead,down:a.down,injuries:Object.entries(a.g.body).filter(([id,p])=>p.hp<85||p.missing).map(([id,p])=>M.partName(id)+': '+(p.missing?'abgetrennt':p.injury||'Verletzt')),blood:Math.round(a.g.blood)})),log:b.log};S.lastReport=report;S.records.unshift(report);S.records=S.records.slice(0,35);M.log((won?'Sieg':'Niederlage')+' gegen '+b.opponent+' · +'+reward+' Gold.');S.battle=null;M.persist();M.sound?.(won?'win':'die');M.onFinish?.(report)}
function cancelQualification(){if(S.battle)return 'Im laufenden Kampf kannst du über AUFGEBEN aussteigen.';if(S.tournament?.type!=='qualification')return 'Keine laufende Qualifikation.';const round=S.tournament.round;S.tournament=null;S.fightLeague=S.league;M.log('Qualifikation vor Runde '+round+' abgebrochen. Die bisherige Liga bleibt erhalten.');M.persist();return 'Qualifikation abgebrochen. Normale Arenakämpfe sind wieder verfügbar.';}
function surrender(){const b=S.battle;if(!b||b.finale)return;b.paused=false;for(const a of b.actors.filter(a=>a.team===0&&!a.g.dead&&!a.down))a.surrendered=true;startFinale(1,'Deine Schule hat aufgegeben. Bewusstlose bleiben dem Urteil der Menge ausgeliefert.')}
function effectsStep(dt){weaponDrips(dt);for(const a of S.battle?.actors||[])if(a.g.bisected)a.splitProgress=Math.min(1,(a.splitProgress||0)+dt*1.8);M.shake=Math.max(0,M.shake-dt*25);M.cheer=Math.max(0,M.cheer-dt);for(const p of effects){if(!p.active)continue;p.life-=dt;if(p.life<=0){p.active=false;continue}p.x+=p.vx*dt;p.y+=p.vy*dt;p.z+=p.vz*dt;p.vz-=160*dt;if(p.groundKind&&p.z<=0)settleParticle(p);}for(const p of M.limbs){p.t+=dt;if(p.t<1.5){p.x+=p.vx*dt;p.y+=p.vy*dt;p.z=Math.max(0,(p.z||0)+(p.vz||0)*dt);p.vz=(p.vz||0)-240*dt;if(p.z===0&&p.vz<0)p.vz*=-.25;p.vx*=Math.exp(-4*dt);p.vy*=Math.exp(-4*dt);p.angle+=dt*5}}for(const p of M.swings)p.life-=dt;M.swings=M.swings.filter(p=>p.life>0);for(const p of M.floaters){p.life-=dt;p.y-=dt*16}M.floaters=M.floaters.filter(p=>p.life>0)}
if(S.battle?.finale&&S.battle.finale.version!==2){const f=S.battle.finale;f.judgments=f.judgments.filter(j=>!j.done);f.index=0;f.stage='cheer';f.elapsed=0;f.version=2;S.battle.cinematic=null;}
if(S.battle?.limbs)M.limbs=S.battle.limbs;if(S.battle?.stains)M.stains=S.battle.stains;
if(S.battle?.projectiles)S.battle.projectiles.forEach((p,i)=>{if(i<shots.length)Object.assign(shots[i],p)});
for(const a of S.battle?.actors||[]){a.roll=0;if(a.state==='roll')a.state='idle';}
function snapshotBattle(){if(!S.battle)return;S.battle.projectiles=shots.filter(p=>p.active).map(p=>({...p}));S.battle.limbs=M.limbs;S.battle.stains=M.stains;}
