'use strict';
// Nahkampf-Reaktionen; flüchtige Posen bleiben außerhalb der Spielstände.
(()=>{
 const M=window.MG,cl=M.clamp,T=M.T;
 const counts={hit:0,dodge:0,block:0,counter:0,whiff:0,glance:0};
 const R={enabled:true,counts,last:null},poses=new WeakMap(),renderPoses=new WeakMap();
 const live=a=>a&&!a.g.dead&&!a.down&&!a.surrendered;
 const standing=a=>live(a)&&!(a.fallTimer>0)&&!(a.kneeTimer>0);
 const applies=(a,b,projectile)=>R.enabled&&!projectile&&!a.hahn&&!b.hahn&&!a.lion&&!b.lion&&!a.rex&&!b.rex;
 function event(kind,a,b,damage=0){counts[kind]++;R.last={kind,attacker:a.g.name,defender:b.g.name,damage,time:M.s.battle?.time||0};}
 function response(a,kind,angle,power,duration,part='chest'){
  if(!standing(a)&&!(kind==='groundHit'&&!a.g.dead&&M.s.battle))return;
  poses.set(a,{kind,angle,power,left:duration,duration,part});
 }
 R.reset=()=>{for(const k in counts)counts[k]=0;R.last=null;};
 R.tick=(a,dt)=>{const r=poses.get(a);if(r){r.left=Math.max(0,r.left-dt);if(!r.left||a.g.dead||(!standing(a)&&r.kind!=='groundHit'))poses.delete(a);}};
 R.force=(a,b,damage,w)=>{
  // Existing damage already scales with strength. This controls only the response.
  const strength=cl(a.g.stats.strength,0,100),balance=cl(b.g.stats.balance,0,100),mass=cl(b.g.weight,45,160);
  return cl((23+strength*.34+Math.min(55,damage)*.45+Math.min(8,w.weight||0)*2.5)*(1-balance*.003)*(80/mass)**.35,24,86);
 };
 R.impulse=(a,b,damage,w,projectile)=>applies(a,b,projectile)&&standing(b)?R.force(a,b,damage,w):null;
 R.push=(a,b,force,projectile)=>{
  if(!applies(a,b,projectile))return false;
  if(!standing(b))return false;
  const angle=M.angle(a,b),x=(b.kx||0)+Math.cos(angle)*force,y=(b.ky||0)+Math.sin(angle)*force,n=Math.hypot(x,y),scale=n>92?92/n:1;
  b.kx=x*scale;b.ky=y*scale;return true;
 };
 R.evade=(a,b,projectile)=>{
  if(!applies(a,b,projectile)||!standing(b))return;
  event('dodge',a,b);response(b,'dodge',M.angle(a,b),.6,.24);
 };
 R.miss=(a,b,projectile)=>{
  if(!applies(a,b,projectile))return null;
  const mobile=standing(b)&&!(b.stun>0)&&!(b.netTimer>0)&&!(b.stagger>0)&&M.limbState(b.g).canBurst;
  if(mobile){R.evade(a,b,false);b.dodges=(b.dodges||0)+1;return 'dodge';}
  // No miraculous dodges by a trapped or fallen fighter: a glancing contact
  // uses the normal block, armour and injury pipeline at reduced raw damage.
  event('glance',a,b);return 'glance';
 };
 R.whiff=(a,b,projectile)=>{if(!applies(a,b,projectile))return;event('whiff',a,b);response(a,'rebound',M.angle(b,a),.35,.18);};
 R.block=(a,b,projectile,w)=>{
  if(!applies(a,b,projectile))return;
  event('block',a,b);const force=R.force(a,b,0,w);
  response(b,'block',M.angle(a,b),cl(force/80,.3,.8),.26);
  response(a,'rebound',M.angle(b,a),.65,.22);
  R.push(a,b,force*.3,false);
 };
 R.counter=(a,b,projectile)=>{
  if(!applies(a,b,projectile))return null;
  event('counter',b,a);
  // A successful parry creates a short opening for a normal, paid attack.
  if(standing(b)&&!(b.stun>0)&&!(b.reloadTimer>0))b.cool=Math.min(b.cool,.12);
  response(a,'rebound',M.angle(b,a),.85,.26);
  return cl(T.counterStunBase+b.g.stats.reflex*T.counterStunReflex,T.counterStunBase,T.counterStunMax);
 };
 R.impact=(a,b,damage,projectile,w,part='chest')=>{
  if(!applies(a,b,projectile))return;
  event('hit',a,b,damage);response(b,'hit',M.angle(a,b),cl(R.force(a,b,damage,w)/86,.28,1),.30,part);
 };
 R.groundImpact=(a,b,damage,w,part='chest')=>{
  if(!applies(a,b,false)||b.g.dead)return;
  response(b,'groundHit',M.angle(a,b),cl(R.force(a,b,damage,w)/86,.28,1),.24,part);
 };
 R.pose=a=>{
  const r=poses.get(a);if(!R.enabled||!r||a.g.dead||(!standing(a)&&r.kind!=='groundHit'))return null;
  const t=cl(1-r.left/r.duration,0,1),pulse=t<.16?t/.16:Math.exp(-4*(t-.16)/.84)*Math.cos((t-.16)/.84*5),k=pulse*r.power;
  const face=Math.cos(a.a)>=0?1:-1,dir=cl(Math.cos(r.angle)*face,-1,1);
  let p=renderPoses.get(a);if(!p){p={};renderPoses.set(a,p);}
  Object.assign(p,{kind:r.kind,k,tilt:0,lean:0,duck:0,dx:0,dy:0,headX:0,headY:0,knee:0});
  if(r.kind==='hit'){
   const head=['head','neck'].includes(r.part),leg=/^(lt|rt|lsh|rsh|lf|rf)$/.test(r.part);
   p.tilt=dir*k*(head?.29:.22);p.lean=dir*k*(head?3.5:5.5);
   p.headX=dir*k*(head?6:2);p.headY=k*(head?-2:1);
   p.knee=Math.max(0,k)*(leg?.28:.10);
  }
  if(r.kind==='groundHit'){p.tilt=k*.07;p.dy=-Math.max(0,k)*1.7;p.headX=dir*k*2;p.headY=-Math.max(0,k);}

  if(r.kind==='block'){p.tilt=dir*Math.max(0,k)*.075;p.lean=dir*Math.max(0,k)*1.5;}
  if(r.kind==='dodge'){const d=Math.max(0,k);p.tilt=dir*d*.12;p.lean=dir*d*5;p.duck=d*4;p.dx=Math.cos(r.angle)*d*3;p.dy=Math.sin(r.angle)*d*3;}
  return p;
 };
 M.combatResponses=R;
})();

